style.css:
@-moz-document domain("roblox.com") {
body, html {
    background-color: #dae8fc !important;
  }

  .navbar, .rbx-navbar, .nav-menu, .game-header, .content {
    background-color: #c9daf8 !important;
    background-image: linear-gradient(to bottom, #e6f0ff, #a8c3e1) !important;
  }

  .container-main, .section, .card, .game-card-container {
    background-color: #eaf3fc !important;
    border: 1px solid #a8c3e1 !important;
    border-radius: 8px;
  }

  /* Text color tweaks */
  .text-label, .text, .font-header-2, h1, h2, h3, p {
    color: #000066 !important;
  }

  /* Buttons */
  .btn-primary, .btn-secondary {
    background-color: #d0e1fd !important;
    color: #003366 !important;
    border: 1px solid #a8c3e1 !important;
  }

  /* Remove dark mode effects if they're being stubborn */
  [class*="dark-theme"] {
    background-color: #dae8fc !important;
    color: #000 !important;
  }
}
